  map:
    '<path d="M12 21c4.2-4.4 6.3-7.6 6.3-10.2A6.3 6.3 0 0 0 12 4.5a6.3 6.3 0 0 0-6.3 6.3C5.7 13.4 7.8 16.6 12 21Z"/>' +
    '<circle cx="12" cy="10.6" r="2.2"/>',
